        pm.expect(json.success).to.eql(true);
        pm.expect(json.data).to.have.property("id");
        pm.expect(json.data.id).to.be.a("number");
    } else {
        pm.expect(json).to.be.an("object");
    }
});

pm.test("Response sesuai data input", function () {
    if (expectedStatus === 201) {
        pm.expect(json.data.title).to.include(csvTitle);
        pm.expect(json.data.description).to.eql(csvDescription);
    } else {
        pm.expect(json).to.exist;
    }
